# ── V89: live header market data ─────────────────────────────────────────
# Ported from xrpcomplete.com's own main.py (_coinbase_candles, fetch_market,
# fetch_header_cards, the active-address/ledger tracker, and the HC3 overlay
# system) so the blog's header shows the same real, live numbers the site
# does -- not a static snapshot. Same data sources, same logic, same
# honesty rule: on a failed fetch the prior value is left in place, nothing
# is invented. This sandbox has no network access to execute-test these
# calls; the code is a direct port of the site's already-working functions.

MARKET = {
    "xrp_price": None, "xrp_chg": None, "mcap": None, "vol24": None,
    "price_ok_ts": None, "hist_1w_hourly": [],
}
HDR = {"btc_price": None, "btc_chg": None, "eth_price": None, "eth_chg": None,
       "xrp_supply": None, "xrp_ath": None, "vol_chg": None, "settle_secs": None,
       "aa": None, "aa_prev": None, "aa_cov": 0.0, "aa_prev_cov": 0.0}


def _coinbase_candles(product_id, granularity=86400, limit=300):
    """Public Coinbase Exchange candles. Returns oldest->newest as
    [time, low, high, open, close, volume] floats. No key needed."""
    hdr = {"User-Agent": "XRPCompleteBlog/1"}
    r = requests.get(f"https://api.exchange.coinbase.com/products/{product_id}/candles",
                      params={"granularity": granularity}, headers=hdr, timeout=8)
    data = r.json()
    if not isinstance(data, list):
        return []
    data.sort(key=lambda c: c[0])
    return data[-limit:]


def fetch_market():
    hdr = {"User-Agent": "XRPCompleteBlog/1"}
    try:
        r = requests.get("https://api.coinpaprika.com/v1/tickers/xrp-xrp", headers=hdr, timeout=8)
        d = r.json()
        q = (d.get("quotes") or {}).get("USD") or {}
        p = float(q.get("price", 0) or 0)
        if p > 0:
            MARKET["xrp_price"] = p
            MARKET["xrp_chg"] = float(q.get("percent_change_24h", 0) or 0)
            MARKET["mcap"] = float(q.get("market_cap", 0) or 0)
            MARKET["vol24"] = float(q.get("volume_24h", 0) or 0)
            MARKET["price_ok_ts"] = time.time()
    except Exception:
        pass
    try:
        k1h = _coinbase_candles("XRP-USD", granularity=3600, limit=200)
        if k1h:
            MARKET["hist_1w_hourly"] = [float(c[4]) for c in k1h][-168:]
    except Exception:
        pass


def fetch_header_cards():
    """BTC / ETH price + 24h change, XRP circulating supply, ATH, 24h volume
    change. Leaves prior values in place on failure; never fabricates."""
    hdr = {"User-Agent": "XRPCompleteBlog/1"}
    for pid, pre in (("btc-bitcoin", "btc"), ("eth-ethereum", "eth"), ("xrp-xrp", "xrp")):
        try:
            d = requests.get(f"https://api.coinpaprika.com/v1/tickers/{pid}", headers=hdr, timeout=8).json()
            q = (d.get("quotes") or {}).get("USD") or {}
            p = float(q.get("price", 0) or 0)
            if p <= 0:
                continue
            if pre == "xrp":
                sup = float(d.get("circulating_supply", 0) or 0)
                ath = float(q.get("ath_price", 0) or 0)
                if sup > 0:
                    HDR["xrp_supply"] = sup
                if ath > 0:
                    HDR["xrp_ath"] = ath
                if q.get("volume_24h_change_24h") is not None:
                    HDR["vol_chg"] = float(q.get("volume_24h_change_24h"))
            else:
                HDR[pre + "_price"] = p
                HDR[pre + "_chg"] = float(q.get("percent_change_24h", 0) or 0)
        except Exception:
            pass


# Active addresses + real ledger close time (settlement speed), read directly
# off the XRP Ledger -- same approach as the site: every validated ledger is
# read, sending/receiving accounts are bucketed by hour, tallied on the hour.
# Starts from zero on deploy, reaches a full 24h window after one day.
_RIPPLE_EPOCH = 946684800
_XRPL_NODES = ["https://xrplcluster.com", "https://s1.ripple.com:51234", "https://s2.ripple.com:51234"]
_AA = {"buckets": {}, "last_seq": None, "first_ts": None, "tally_hour": None,
       "closes": collections.deque(maxlen=120)}


def _xrpl_call(method, params):
    hdr = {"User-Agent": "XRPCompleteBlog/1", "Content-Type": "application/json"}
    for node in _XRPL_NODES:
        try:
            r = requests.post(node, json={"method": method, "params": [params]}, headers=hdr, timeout=10)
            res = r.json().get("result") or {}
            if res.get("status") == "success":
                return res
        except Exception:
            continue
    return None


def _aa_tally(now_hour):
    lo = now_hour - 24 * 3600
    u = set()
    for h, s in list(_AA["buckets"].items()):
        if lo <= h < now_hour:
            u |= s
    cov = 0.0
    if _AA["first_ts"]:
        cov = max(0.0, min(24.0, (now_hour - _AA["first_ts"]) / 3600.0))
    if cov > 0:
        HDR["aa_prev"], HDR["aa_prev_cov"] = HDR["aa"], HDR["aa_cov"]
        HDR["aa"], HDR["aa_cov"] = len(u), cov
    for h in [h for h in _AA["buckets"] if h < now_hour - 25 * 3600]:
        _AA["buckets"].pop(h, None)


def _bg_active_addr():
    while True:
        try:
            now_hour = int(time.time()) // 3600 * 3600
            if _AA["tally_hour"] is None:
                _AA["tally_hour"] = now_hour
            elif now_hour > _AA["tally_hour"]:
                _aa_tally(now_hour)
                _AA["tally_hour"] = now_hour

            v = _xrpl_call("ledger", {"ledger_index": "validated"})
            top = int(v["ledger_index"]) if v and v.get("ledger_index") else None
            if top is None:
                time.sleep(10)
                continue
            if _AA["last_seq"] is None or top - _AA["last_seq"] > 900:
                _AA["last_seq"] = top - 1
            while _AA["last_seq"] < top:
                seq = _AA["last_seq"] + 1
                res = _xrpl_call("ledger", {"ledger_index": seq, "transactions": True, "expand": True})
                if not res:
                    break
                led = res.get("ledger") or {}
                ct = led.get("close_time")
                if ct is None:
                    break
                ts = int(ct) + _RIPPLE_EPOCH
                bucket = _AA["buckets"].setdefault(ts // 3600 * 3600, set())
                for tx in led.get("transactions") or []:
                    if isinstance(tx, dict):
                        for f in ("Account", "Destination"):
                            a = tx.get(f)
                            if isinstance(a, str):
                                bucket.add(a)
                if _AA["first_ts"] is None:
                    _AA["first_ts"] = ts
                _AA["closes"].append((seq, ts))
                if len(_AA["closes"]) >= 20:
                    (s0, t0), (s1, t1) = _AA["closes"][0], _AA["closes"][-1]
                    if s1 > s0:
                        HDR["settle_secs"] = (t1 - t0) / (s1 - s0)
                _AA["last_seq"] = seq
        except Exception:
            pass
        time.sleep(2)


def _fmt_usd(v):
    if not v:
        return "\u2014"
    if v >= 1e9:
        return f"${v / 1e9:.2f}B"
    if v >= 1e6:
        return f"${v / 1e6:.2f}M"
    if v >= 1e3:
        return f"${v / 1e3:.1f}K"
    return f"${v:.2f}"


def _fmt_num(v):
    if not v:
        return "\u2014"
    if v >= 1e9:
        return f"{v / 1e9:.2f}B"
    if v >= 1e6:
        return f"{v / 1e6:.2f}M"
    if v >= 1e3:
        return f"{v / 1e3:.1f}K"
    return f"{v:.2f}"


def _fmt_price(v):
    if not v:
        return "\u2014"
    if v >= 1:
        return f"${v:,.2f}"
    if v >= 0.01:
        return f"${v:.4f}"
    return f"${v:.6f}"


def _hc3_chg(v, dec=2, suffix=""):
    if v is None:
        return ""
    up = v >= 0
    col = "#4ade80" if up else "#f0596b"
    arrow = "\u25B2" if up else "\u25BC"
    sign = "+" if up else "-"
    return f'<span style="color:{col}">{arrow}{sign}{abs(v):.{dec}f}%</span>{suffix}'


def header_live_html():
    ts = MARKET.get("price_ok_ts")
    age = (time.time() - ts) if ts else None
    if age is not None and age < 180:
        st, txt = "ok", "LIVE"
    elif age is not None and age < 900:
        st, txt = "warn", "DELAYED"
    else:
        st, txt = "down", "OFFLINE"
    return f'<span class="lv3 lv3-{st}"><span class="lv3-dot"></span>{txt}</span>'


def header_cards_values():
    p, c = MARKET.get("xrp_price"), MARKET.get("xrp_chg")
    dash = "\u2014"
    xp = f"${p:.4f}" if p else dash
    aa, cov = HDR.get("aa"), HDR.get("aa_cov") or 0
    if aa is None:
        aa_html = f'{dash} <span class="v-sm v-dim">first tally at :00</span>'
    else:
        if cov >= 24 and HDR.get("aa_prev") and (HDR.get("aa_prev_cov") or 0) >= 24:
            sub = _hc3_chg((aa - HDR["aa_prev"]) / HDR["aa_prev"] * 100, 1)
        else:
            sub = f'<span class="v-dim">{cov:.0f}h of data</span>'
        aa_html = f'{_fmt_num(aa).replace(".00", "")} <span class="v-sm">{sub}</span>'
    st = HDR.get("settle_secs")
    return {
        "price": xp,
        "chg": (_hc3_chg(c, 2, ' <span class="v-dim">(24h)</span>') if p else ""),
        "mcap": _fmt_usd(MARKET.get("mcap")),
        "vol": _fmt_usd(MARKET.get("vol24")),
        "sup": (_fmt_num(HDR["xrp_supply"]) + " XRP") if HDR.get("xrp_supply") else dash,
        "ath": _fmt_price(HDR.get("xrp_ath")),
        "gvol": f'{_fmt_usd(MARKET.get("vol24"))} <span class="v-sm">{_hc3_chg(HDR.get("vol_chg"), 1)}</span>',
        "aa": aa_html,
        "settle": (f"{st:.1f}s" if st else dash),
        "btc": (f'${HDR["btc_price"]:,.0f} <span class="v-sm">{_hc3_chg(HDR.get("btc_chg"), 1)}</span>' if HDR.get("btc_price") else dash),
        "eth": (f'${HDR["eth_price"]:,.0f} <span class="v-sm">{_hc3_chg(HDR.get("eth_chg"), 1)}</span>' if HDR.get("eth_price") else dash),
        "xrpm": (f'{xp} <span class="v-sm">{_hc3_chg(c, 1)}</span>' if p else dash),
        "live": header_live_html(),
    }


def xrp_chart_svg(closes, width=594, height=230):
    """Real SVG line built from live Coinbase hourly closes, not a decorative
    image. Returns '' when no data yet (first few seconds after boot)."""
    closes = [c for c in (closes or []) if c]
    if len(closes) < 2:
        return ""
    lo, hi = min(closes), max(closes)
    span = (hi - lo) or (lo * 0.001) or 1
    pad = height * 0.08
    n = len(closes)
    pts = []
    for i, c in enumerate(closes):
        x = i / (n - 1) * width
        y = pad + (1 - (c - lo) / span) * (height - 2 * pad)
        pts.append(f"{x:.1f},{y:.1f}")
    line = " ".join(pts)
    area = f"0,{height:.0f} " + line + f" {width:.0f},{height:.0f}"
    up = closes[-1] >= closes[0]
    color = "#4ade80" if up else "#f0596b"
    return (
        f'<svg viewBox="0 0 {width} {height}" preserveAspectRatio="none" '
        f'style="position:absolute;inset:0;width:100%;height:100%">'
        f'<defs><linearGradient id="cf" x1="0" y1="0" x2="0" y2="1">'
        f'<stop offset="0%" stop-color="{color}" stop-opacity="0.32"/>'
        f'<stop offset="100%" stop-color="{color}" stop-opacity="0"/>'
        f'</linearGradient></defs>'
        f'<polygon points="{area}" fill="url(#cf)"/>'
        f'<polyline points="{line}" fill="none" stroke="{color}" stroke-width="2.4" '
        f'stroke-linejoin="round" stroke-linecap="round"/>'
        f'</svg>'
    )


_HERO_VALUE_KEYS = ("price", "chg", "mcap", "vol", "sup", "ath",
                    "gvol", "aa", "settle", "btc", "eth", "xrpm")


def hero_cards():
    """Same shape as xrpcomplete.com's hero_cards() (kept byte-identical
    on purpose) — real (non-positioned) HTML fragments for each live
    value, each wrapped in a stable id="v-KEY" for the 60s JS refresh
    poll. The boxes/labels around these are static markup in HEADER_BLOCK
    now, not %-coordinates pinned to a raster image."""
    vals = header_cards_values()
    frags = {k: f'<span id="v-{k}">{vals[k]}</span>' for k in _HERO_VALUE_KEYS}
    frags["live_pill"] = f'<span id="v-live">{vals["live"]}</span>'
    frags["chart"] = f'<div id="v-chart" class="panel-chart">{xrp_chart_svg(MARKET.get("hist_1w_hourly"))}</div>'
    return frags


